-- A computed column with its own index
ALTER TABLE dbo.Orders ADD CreatedYear AS YEAR(CreatedAt);
CREATE INDEX IX_Orders_CreatedYear ON dbo.Orders (CreatedYear);
-- Tested: WHERE YEAR(CreatedAt) = 2026 now seeks, 150 reads

-- An index on an expression (example from the PostgreSQL docs)
CREATE INDEX orders_lower_email_idx ON orders (lower(email));
SELECT id FROM orders WHERE lower(email) = 'ana@example.com';
